//! Cross-feature cases: suspension inside deeper constructs, async + classes, proxies over
//! collections and array-likes, Reflect with the new function kinds.

pub const CASES: &[(&str, &str)] = &[
    // generators: suspension points in awkward places
    ("function* g() { try { throw 1; } catch (e) { const x = yield e; yield x * 2; } finally { yield 'fin'; } } const it = g(); [it.next().value, it.next(5).value, it.next().value, it.next().done].join()", "1,10,fin,true"),
    ("function* g() { yield [1, yield 2, 3].length + (yield 4); } const it = g(); it.next(); it.next(); JSON.stringify(it.next(10))", "{\"value\":13,\"done\":false}"),
    ("function f(a, b, c) { return a + b + c; } function* g() { yield f(yield 'a', yield 'b', yield 'c'); } const it = g(); it.next(); it.next(1); it.next(2); it.next(3).value", "6"),
    ("function* g() { const o = { a: yield 1, [yield 2]: yield 3 }; yield JSON.stringify(o); } const it = g(); it.next(); it.next('A'); it.next('k'); it.next('V').value", "{\"a\":\"A\",\"k\":\"V\"}"),
    ("function* g() { yield 1; yield 2; } Math.max(...g())", "2"),
    ("function* nat() { let n = 0; while (true) yield n++; } function* take(it, k) { for (const v of it) { if (k-- <= 0) return; yield v; } } [...take(nat(), 5)].join()", "0,1,2,3,4"),
    ("let log = []; function* inner() { try { yield 1; yield 2; } finally { log.push('inner done'); } } function* outer() { for (const v of inner()) { yield v; return 'early'; } } const r = [...outer()]; r.join() + '|' + log.join()", "1|inner done"),
    ("function* g() { let i = 0; do { if (i === 1) { i++; continue; } yield i++; } while (i < 4); } [...g()].join()", "0,2,3"),
    ("function* g() { outer: for (const a of [1, 2]) { for (const b of [10, 20]) { if (b === 20) continue outer; yield a + b; } } } [...g()].join()", "11,12"),
    ("class Tree { constructor(v, kids = []) { this.v = v; this.kids = kids; } *[Symbol.iterator]() { yield this.v; for (const k of this.kids) yield* k; } } [...new Tree(1, [new Tree(2, [new Tree(3)]), new Tree(4)])].join()", "1,2,3,4"),
    ("function* g() { const self = yield; yield self === it; } const it = g(); it.next(); it.next(it).value", "true"),
    // 300 generator frames deep: resuming switches VM frames instead of recursing natively
    ("function* count(n) { if (n > 0) { yield n; yield* count(n - 1); } } let s = 0; for (const v of count(300)) s += v; s", "45150"),
    ("class A { async constructor() {} }", "SyntaxError!"),
    ("function* g() { yield* g2(); } function* g2() { yield typeof (yield 'first'); } const it = g(); it.next(); it.next(7).value", "number"),
    ("const o = { *g() { yield super.toString === Object.prototype.toString; } }; o.g().next().value", "true"),
    // async: awaits in awkward places
    ("var out = []; async function f() { try { throw new Error('x'); } finally { await null; out.push('fin'); } } f().catch(e => out.push(e.message));", "fin,x"),
    ("var out; async function f() { return Promise.reject(new Error('r')); } f().catch(e => { out = e.message; });", "r"),
    ("var out; async function f(x) { return (await x) ? await 'yes' : await 'no'; } Promise.all([f(1), f(0)]).then(v => { out = v.join(); });", "yes,no"),
    ("var out; async function f() { return `${await 1}-${await 2}` + String(await Math.max(await 3, await 4)); } f().then(v => { out = v; });", "1-24"),
    ("var out; class A { async m() { return 'A'; } } class B extends A { async m() { return (await super.m()) + 'B'; } } new B().m().then(v => { out = v; });", "AB"),
    ("var out; class C { v = 5; get = async () => this.v; } new C().get().then(v => { out = v; });", "5"),
    ("var out; async function f() { const r = []; for (let i = 0; i < 3; i++) { await null; r.push(() => i); } return r.map(g => g()).join(); } f().then(v => { out = v; });", "0,1,2"),
    ("var out; (async () => { try { await { then() { throw new Error('t'); } }; } catch (e) { out = e.message; } })();", "t"),
    ("var out; Promise.all([1, 2, 3].map(async x => x * 2)).then(v => { out = v.join(); });", "2,4,6"),
    ("var out = []; [1, 2, 3].forEach(async x => { await null; out.push(x); }); out.push('sync');", "sync,1,2,3"),
    ("var out = []; const delay = (v, n) => new Promise(r => { let i = 0; const tick = () => (i++ < n ? queueMicrotask(tick) : r(v)); tick(); }); (async () => { const a = delay('a', 5), b = delay('b', 1); out.push(await a, await b); out.push(await Promise.race([delay('slow', 9), delay('fast', 2)])); })();", "a,b,fast"),
    ("var out; async function f() { let n = 0; while (n < 100) { n += await 1; if (n % 2) continue; await undefined; } return n; } f().then(v => { out = v; });", "100"),
    ("var out; async function f() { const [a, { b }, ...rest] = await Promise.resolve([1, { b: 2 }, 3, 4]); return a + b + rest.length; } f().then(v => { out = v; });", "5"),
    ("var out; const o = { async m() { return this === o; } }; o.m().then(v => { out = v; });", "true"),
    ("var out; async function f() { return arguments.length + (await arguments[0]); } f(Promise.resolve(40), 0).then(v => { out = v; });", "42"),
    ("var out = []; async function* countdown(n) { while (n > 0) { yield n--; await null; } } (async () => { for await (const v of countdown(3)) { out.push(v); await null; } out.push('liftoff'); })();", "3,2,1,liftoff"),
    ("var out = []; async function* g() { yield* [1, 2]; yield* (async function* () { yield 3; })(); } (async () => { for await (const v of g()) out.push(v); })();", "1,2,3"),
    ("var out; async function* g() { yield 1; } const it = g(); Promise.all([it.next(), it.return('r'), it.next()]).then(rs => { out = rs.map(r => r.value + ':' + r.done).join(); });", "1:false,r:true,undefined:true"),
    ("var out; async function* g() { throw new Error('first'); } const it = g(); it.next().then(() => {}, e => it.next().then(r => { out = e.message + ',' + r.done; }));", "first,true"),
    // collections with the other features
    ("const m = new Map([[1, 'a']]); const p = new Proxy(m, { get(t, k) { const v = Reflect.get(t, k); return typeof v === 'function' ? v.bind(t) : v; } }); p.get(1) + p.size", "a1"),
    ("Map.prototype.set.call(new Proxy(new Map(), {}), 1, 1)", "TypeError!"),
    ("function* pairs() { yield [1, 'x']; yield [2, 'y']; } const m = new Map(pairs()); const s = new Set(m.values()); [...s].join() + m.size", "x,y2"),
    ("var out; const cache = new Map(); async function load(k) { if (!cache.has(k)) cache.set(k, Promise.resolve(k * 2)); return cache.get(k); } Promise.all([load(1), load(1), load(2)]).then(v => { out = v.join() + ':' + cache.size; });", "2,2,4:2"),
    ("const wm = new WeakMap(); function* g() { const k = {}; wm.set(k, 'held'); yield k; } const it = g(); const k = it.next().value; wm.get(k)", "held"),
    ("const groups = new Map(); for (const w of ['apple', 'avocado', 'banana']) { const k = w[0]; groups.set(k, [...(groups.get(k) || []), w]); } [...groups].map(([k, v]) => k + '=' + v.length).join()", "a=2,b=1"),
    // proxies over array-likes and classes
    ("const p = new Proxy({ a: 1, b: 2 }, { get: (t, k) => t[k] + 1 }); JSON.stringify(Object.assign({}, p))", "{\"a\":2,\"b\":3}"),
    ("Array.prototype.map.call(new Proxy([1, 2, 3], {}), x => x * 2).join()", "2,4,6"),
    ("class A {} const P = new Proxy(A, {}); [new A() instanceof P, new P() instanceof A, P.name].join()", "true,true,A"),
    ("const calls = []; const p = new Proxy([3, 1, 2], { get(t, k, r) { if (typeof k === 'string' && /x/.source && k === 'length') calls.push('len'); return Reflect.get(t, k, r); } }); const sorted = [...p].sort().join(''); sorted + ':' + (calls.length > 0)", "123:true"),
    ("const p = new Proxy({}, { get: (t, k) => k === 'then' ? undefined : 'v' }); var out; Promise.resolve(p).then(v => { out = v === p; });", "true"),
    ("var out; const lazy = new Proxy({}, { get: (t, k) => k === 'then' ? (res => res('proxied thenable')) : undefined }); (async () => { out = await lazy; })();", "proxied thenable"),
    ("function* g() { yield 1; yield 2; } const p = new Proxy(g(), { get(t, k) { const v = t[k]; return typeof v === 'function' ? v.bind(t) : v; } }); [...p].join()", "1,2"),
    // Reflect with the new function kinds
    ("Reflect.apply(function* () { yield 1; }, null, []).next().value", "1"),
    ("class M extends Map {} [Reflect.construct(Map, [[[1, 2]]]).get(1), Reflect.construct(Map, [], M) instanceof M].join()", "2,true"),
    ("Reflect.defineProperty({}, 'x', 5)", "TypeError!"),
    ("Reflect.set({}, 'x', 1, 5) + ',' + Reflect.has([], 'length')", "false,true"),
    ("Reflect.ownKeys('str')", "TypeError!"),
    ("var out; Reflect.apply(async function () { return this.v; }, { v: 9 }, []).then(v => { out = v; });", "9"),
];
